function summarizeProfile(response) {
  const { profile: rawProfile } = response ?? {};
  const profile = rawProfile ?? {};
  const { displayName, score, tags, preferences } = profile;
  const [primaryTag = "general", ...otherTags] = tags ?? [];

  return {
    displayName: displayName ?? "Guest",
    score: score ?? 0,
    primaryTag,
    otherTags,
    theme: preferences?.theme ?? "system",
  };
}

console.log(summarizeProfile({ profile: { displayName: "", score: 0, tags: ["ui", "react"] } }));
